class SizeTest {
    static void check(String label, int got, int want) {
        if (got != want) throw new AssertionError(label + ": got " + got + ", want " + want);
        System.out.println("OK " + label);
    }

    public static void main(String[] args) {
        Trie t = new Trie();
        check("empty",             t.size(), 0);

        t.insert("and");
        check("after insert and",  t.size(), 1);
        t.insert("ant");
        check("after insert ant",  t.size(), 2);
        t.insert("do");
        t.insert("dad");
        check("after 4 inserts",   t.size(), 4);

        // re-inserting an existing word must not change the count
        t.insert("and");
        check("duplicate insert",  t.size(), 4);

        // deleting a word that exists
        t.delete("ant");
        check("after delete ant",  t.size(), 3);

        // deleting a word that is not in the trie must not change the count
        t.delete("ant");
        check("delete absent",     t.size(), 3);
        t.delete("xyz");
        check("delete nonexistent",t.size(), 3);

        // delete remaining words down to zero
        t.delete("and");
        t.delete("do");
        t.delete("dad");
        check("after all deleted", t.size(), 0);
    }
}
